import json, sys, os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PORT = int(sys.argv[1])
LOG = '/tmp/shyt/requests.jsonl'
TRACES = '/tmp/shyt/traces'
os.makedirs(TRACES, exist_ok=True)


def tc(i, name, args):
    return {"id": f"call_{i}_{name}", "type": "function", "function": {"name": name, "arguments": json.dumps(args)}}


def reply(msg, finish="stop"):
    return {"id": "gen-1", "model": "mock/model-1", "provider": "Mock",
            "choices": [{"index": 0, "finish_reason": finish, "message": msg}],
            "usage": {"prompt_tokens": 1200, "completion_tokens": 85, "total_tokens": 1285, "cost": 0.0012345,
                      "prompt_tokens_details": {"cached_tokens": 1000},
                      "completion_tokens_details": {"reasoning_tokens": 20}}}


def scenario(body):
    msgs = body["messages"]
    sub = "running as a subagent" in msgs[0]["content"]
    stage = sum(1 for m in msgs if m["role"] == "assistant")
    user = [m for m in msgs if m["role"] == "user"][-1]["content"]
    if user.startswith("plain"):
        return reply({"role": "assistant", "content": "Just text: \"quoted\" 😀\nline2"})
    if user.startswith("fail"):
        return None
    if sub:
        if stage == 0:
            return reply({"role": "assistant", "content": "Sub looking.",
                          "tool_calls": [tc(9, "bash", {"command": "echo from-sub; ls /nonexistent-dir"})]}, "tool_calls")
        return reply({"role": "assistant", "content": "SUB RESULT: saw from-sub"})
    if stage == 0:
        return reply({"role": "assistant", "content": "Let me work.", "reasoning": "I should write then read.",
                      "reasoning_details": [{"type": "reasoning.text", "text": "think", "format": "x"}],
                      "tool_calls": [
                          tc(1, "write", {"path": "out/hello.sh", "content": "#!/bin/bash\necho \"hello\\tworld\" 'q'\n\\back\n😀\n"}),
                          tc(2, "read", {"path": "out/hello.sh"}),
                          tc(3, "edit", {"path": "out/hello.sh", "oldText": "echo \"hello", "newText": "printf '%s\\n' \"HELLO"}),
                          tc(4, "bash", {"command": "cat out/hello.sh; printf '\\033[31mred\\033[0m\\n'; exit 3"}),
                      ]}, "tool_calls")
    if stage == 1:
        return reply({"role": "assistant", "content": None, "tool_calls": [
            tc(5, "webfetch", {"url": f"http://127.0.0.1:{PORT}/page"}),
            tc(6, "subagent", {"task": "Run echo and report"}),
            tc(7, "edit", {"path": "out/hello.sh", "oldText": "does-not-exist", "newText": "x"}),
            tc(8, "nope", {}),
        ]}, "tool_calls")
    return reply({"role": "assistant", "content": "All done. Wrote out/hello.sh."})


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def send(self, code, obj, ctype="application/json"):
        data = obj if isinstance(obj, bytes) else json.dumps(obj).encode()
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path == "/page":
            html = b"""<!doctype html><html><head><title>Mock &amp; Page</title><style>body{color:red}</style>
<script>if (a<b) { alert("x") }</script></head><body><h1>Heading</h1><p>First   paragraph
with <b>bold</b> &lt;tag&gt; text.</p><ul><li>one</li><li>two</li></ul></body></html>"""
            return self.send(200, html, "text/html; charset=utf-8")
        self.send(404, {"error": "nf"})

    def do_POST(self):
        raw = self.rfile.read(int(self.headers.get("Content-Length", 0)))
        try:
            body = json.loads(raw.decode("utf-8"))
        except Exception as e:
            return self.send(400, {"error": {"message": f"mock: invalid JSON body: {e}"}})
        if self.path == "/v1/trace":
            n = len(os.listdir(TRACES))
            with open(f"{TRACES}/{n:03d}.json", "w") as f:
                json.dump({"headers": {k.lower(): v for k, v in self.headers.items()}, "body": body}, f)

            def count(s):
                return 1 + sum(count(c) for c in s.get("children", []))
            return self.send(200, {"success": True, "trace_id": "%032x" % (n + 1), "spans": count(body)})
        with open(LOG, "a") as f:
            f.write(json.dumps({"auth": self.headers.get("Authorization"), "body": body}) + "\n")
        r = scenario(body)
        if r is None:
            return self.send(400, {"error": {"message": "mock: model refused", "code": 400}})
        self.send(200, b"\n\n   " + json.dumps(r).encode())


ThreadingHTTPServer(("127.0.0.1", PORT), H).serve_forever()

