# Byte slicing can split a UTF-8 character, and APIs reject invalid UTF-8.
# utf8_head: REPLY = $1 minus a partial character at the end.
utf8_head() {
  local s=$1 n c need
  for n in 1 2 3 4; do
    ((n > ${#s})) && break
    c=${s:${#s}-n:1}
    case $c in
      ["$U_CONT"]) continue ;;
      ["$U_LEAD2"]) need=2 ;;
      ["$U_LEAD3"]) need=3 ;;
      ["$U_LEAD4"]) need=4 ;;
      *) break ;;
    esac
    ((n < need)) && s=${s:0:${#s}-n}
    break
  done
  REPLY=$s
}

# utf8_tail: REPLY = $1 minus a partial character at the start.
utf8_tail() {
  local s=$1 n=0
  while ((n < 3)) && [[ $s == ["$U_CONT"]* ]]; do
    s=${s:1}
    n=$((n + 1))
  done
  REPLY=$s
}

